{"summary": "Run schema checks on solution.json for segment_id format and substring constraint", "command": "python3 - <<'PY'
import json, re
from pathlib import Path
obj=json.loads(Path('/app/output/solution.json').read_text(encoding='utf-8'))
seg_pat=re.compile(r'^R\d{7}-S\d+$')
errors=0
for r in obj['records']:
    raw=r['raw_reason_text']
    for s in r['normalized']:
        if not seg_pat.match(s['segment_id']):
            errors+=1
            if errors<5:
                print('bad segment_id',s['segment_id'])
        if s['span_text'] and s['span_text'] not in raw:
            errors+=1
            if errors<5:
                print('span not substring',r['record_id'],repr(s['span_text']),repr(raw))
        if not (0.0 <= s['confidence'] <= 1.0):
            errors+=1
            if errors<5:
                print('bad confidence',s['confidence'])
        if s['pred_code']=='UNKNOWN' and s['pred_label']!='':
            errors+=1
            if errors<5:
                print('unknown has label',s)
print('total_errors',errors)
PY", "security_risk": "LOW"}

